    const qualityFilter = settings.depthSigma <= QUALITY_FIREFLY_DEPTH_SIGMA_MAX;
    const schedule = !qualityFilter || sampleCount > QUALITY_FULL_DENOISE_SAMPLES_MAX ? ATROUS_DENOISE_STEPS : sampleCount <= QUALITY_SPARSE_DENOISE_SAMPLES_MAX ? QUALITY_SPARSE_DENOISE_STEPS : QUALITY_LOW_SAMPLE_DENOISE_STEPS;
    const step = schedule[iteration];
